 // Read before the probe arms, so the dumpsys round trip stays outside the
 // measured action. Outside native Android there is nothing to read and the tap
 // keeps its centre.
-export function nativeTapPoint(client, bounds, label, readWindows = readAndroidInputWindows) {
+export function nativeTapPoint(client, bounds, label, readWindows = readAndroidInputWindows, nativeWindow = null) {
   const target = client.androidTouchTarget;
   const windows = target ? readWindows(target.serial) : null;
   const point = unoccludedTapPoint(bounds, windows, target?.packageName);
+  if (client.platformName?.toLowerCase() === 'ios' && nativeWindow && point.y > nativeWindow.y + nativeWindow.height - 44) {
+    // The compact action drawer overlaps the home-indicator gesture region on
+    // iPhone. A centre tap there is consumed by iOS before Safari receives it.
+    const safeY = nativeWindow.y + nativeWindow.height - 44;
+    if (bounds.y + 8 <= safeY) point.y = Math.max(bounds.y + 8, Math.min(point.y, safeY));
+  }
   if (point.occludedBy) {
     console.warn(
       `[ipad-actions] ${label}: the target's centre is obscured by ${point.occludedBy.window} ` +
